-- =============================================================================
-- Transgar - 40: Cargas de combustible desde hoja 'Control de Combustible'
-- Solo filas con galones>0. Resuelve vehículo (numero_interno) y conductor (documento).
-- no_factura sintético TMC-<fila>. Ruta -> observaciones. Requiere 00,20,30.
-- =============================================================================
SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON; SET NOCOUNT ON;
DECLARE @IdEmpresa INT = (SELECT id_empresa FROM dbo.empresas WHERE codigo='TRANSGAR');
IF @IdEmpresa IS NULL BEGIN RAISERROR('Empresa TRANSGAR no existe. Ejecute 00 primero.',16,1); RETURN; END
DECLARE @Ahora DATETIME2(3)=SYSUTCDATETIME();
IF OBJECT_ID('tempdb..#comb') IS NOT NULL DROP TABLE #comb;
CREATE TABLE #comb (nofac varchar(50), unidad varchar(20), doc varchar(30), fecha date, galones decimal(12,3), precio decimal(18,4), km decimal(12,2), ruta nvarchar(500));
