SELECT @IdEmpresa, v.id_vehiculo, c.fecha, c.nofac, 'DIESEL', 'GAL', c.galones, c.precio, 'HNL', c.km, p.id_persona, c.ruta, 0, 'seed-transgar', @Ahora
FROM #comb c
JOIN dbo.vehiculos v ON v.id_empresa=@IdEmpresa AND v.numero_interno=c.unidad AND v.eliminado=0
LEFT JOIN dbo.personas p ON p.id_empresa=@IdEmpresa AND p.documento=c.doc AND p.eliminado=0
WHERE NOT EXISTS (SELECT 1 FROM dbo.cargas_combustible x WHERE x.id_empresa=@IdEmpresa AND x.no_factura=c.nofac AND x.eliminado=0);
PRINT 'Cargas de combustible insertadas: '+CAST(@@ROWCOUNT AS varchar(10));
DROP TABLE #comb;
PRINT '=== 40 completado ===';
